const fileId = $input.first().json.id;
const fileName = $input.first().json.name;
const createdTime = new Date($input.first().json.createdTime);
const staticData = $getWorkflowStaticData('global');

if (!staticData.processedFiles) {
  staticData.processedFiles = {};
}

if (staticData.processedFiles[fileId]) {
  console.log(`⏭️ Skipping already processed file: ${fileName}`);
  return [];
}

const now = Date.now();
const fiveMinutesAgo = now - (2 * 60 * 1000);

if (createdTime.getTime() < fiveMinutesAgo) {
  console.log(`⏭️ Skipping old file: ${fileName}`);
  return [];
}

staticData.processedFiles[fileId] = {
  name: fileName,
  processedAt: now,
  createdTime: createdTime.toISOString()
};

const processedIds = Object.keys(staticData.processedFiles);
if (processedIds.length > 100) {
  const sorted = processedIds
    .map(id => ({ id, time: staticData.processedFiles[id].processedAt }))
    .sort((a, b) => b.time - a.time)
    .slice(0, 100);
  const newProcessedFiles = {};
  sorted.forEach(item => {
    newProcessedFiles[item.id] = staticData.processedFiles[item.id];
  });
  staticData.processedFiles = newProcessedFiles;
}

console.log(`✅ Processing new file: ${fileName}`);
return [$input.first()];

